item.content:encoded:
{
  "id": "sin-gastos-hormiga",
  "title": "Sin gastos hormiga",
  "description": "Evitá gastos chicos e innecesarios: cafés de más, antojos, compras impulsivas menores a $3.000.",
  "order": 0
}

{
  "id": "chau-una-suscripcion",
  "title": "Chau una suscripción",
  "description": "Cancelá al menos una suscripción que no estés usando (streaming, apps, gimnasio, etc.).",
  "order": 1
}

{
  "id": "semana-de-venta",
  "title": "Semana de venta",
  "description": "Vendé o intercambiá algo que no usás (ropa, tecnología, libros) y sumá esa plata a tu ahorro.",
  "order": 2
}

{
  "id": "ahorro-intacto",
  "title": "Ahorro intacto",
  "description": "No toques ni un peso de tus ahorros esta semana, pase lo que pase.",
  "order": 3
}

{
  "id": "registro-total",
  "title": "Registro total",
  "description": "Anotá cada peso que gastás, por chico que sea, toda la semana.",
  "order": 4
}

{
  "id": "semana-sin-delivery",
  "title": "Semana sin delivery",
  "description": "Nada de Uber Eats ni Rappi: cociná o llevá tu colación todos los días.",
  "order": 5
}

{
  "id": "solo-efectivo",
  "title": "Solo efectivo",
  "description": "Retirá un monto fijo para la semana y usá solo eso, nada de tarjeta.",
  "order": 6
}

{
  "id": "cazador-de-precios",
  "title": "Cazador de precios",
  "description": "Elegí una compra pendiente y comparala en al menos dos lugares antes de pagarla.",
  "order": 7
}

{
  "id": "dia-cero",
  "title": "Día cero",
  "description": "Elegí un día esta semana en el que no gastes absolutamente nada.",
  "order": 8
}

{
  "id": "detox-de-compras",
  "title": "Detox de compras",
  "description": "Dejá de seguir, aunque sea por esta semana, las cuentas o apps que más ganas de comprar te dan.",
  "order": 9
}

{
  "id": "revisa-tu-cartola",
  "title": "Revisá tu cartola",
  "description": "Repasá tu último estado de cuenta y marcá los gastos que no volverías a hacer.",
  "order": 10
}

{
  "id": "ahorro-hormiga",
  "title": "Ahorro hormiga",
  "description": "Guardá al menos $1.000 todos los días de la semana, aunque sea en una alcancía.",
  "order": 11
}

{
  "id": "lista-antes-de-ir",
  "title": "Lista antes de ir",
  "description": "No entres al supermercado sin una lista armada de antemano.",
  "order": 12
}

{
  "id": "fuera-del-fomo",
  "title": "Fuera del FOMO",
  "description": "No compres nada solo porque está \"en oferta\" o por tiempo limitado.",
  "order": 13
}

{
  "id": "cuenta-tus-intereses",
  "title": "Cuenta tus intereses",
  "description": "Si tenés deudas o compras en cuotas, calculá cuánto te están costando en intereses.",
  "order": 14
}

{
  "id": "regalo-con-manos",
  "title": "Regalo con manos",
  "description": "Si tenés que regalar algo esta semana, que sea hecho por vos, no comprado.",
  "order": 15
}

{
  "id": "un-no-con-onda",
  "title": "Un \"no\" con onda",
  "description": "Decile que no a un plan o salida que no podés costear esta semana.",
  "order": 16
}

{
  "id": "vaciar-la-despensa",
  "title": "Vaciar la despensa",
  "description": "Cociná con lo que ya tenés en casa antes de comprar algo nuevo.",
  "order": 17
}

{
  "id": "foto-a-tus-ingresos",
  "title": "Registrá tus ingresos",
  "description": "Anotá con claridad cuánto entra realmente este mes (sueldo líquido, extras, etc.).",
  "order": 18
}

{
  "id": "transporte-low-cost",
  "title": "Transporte low cost",
  "description": "Elegí la opción más económica para moverte toda la semana (Bip!, bici, a pie).",
  "order": 19
}

{
  "id": "compra-pensada",
  "title": "Compra pensada",
  "description": "Si necesitás comprar algo esta semana, buscá primero si existe de segunda mano.",
  "order": 20
}

{
  "id": "fondo-aparte",
  "title": "Fondo aparte",
  "description": "Empezá o sumá a un fondo de emergencia, aunque sea con $5.000.",
  "order": 21
}

{
  "id": "chequeo-gastos-fijos",
  "title": "Chequeo de gastos fijos",
  "description": "Revisá luz, agua, internet y plan de celular: buscá algo para renegociar.",
  "order": 22
}

{
  "id": "closet-challenge",
  "title": "Clóset challenge",
  "description": "No compres ropa nueva esta semana; usá lo que ya tenés.",
  "order": 23
}

{
  "id": "a-medias",
  "title": "A medias",
  "description": "Buscá compartir algún gasto fijo (streaming, compras grandes) con alguien más.",
  "order": 24
}

{
  "id": "el-gasto-que-pesa",
  "title": "El gasto que pesa",
  "description": "Identificá un gasto que te genera culpa y decidí a conciencia si lo mantenés.",
  "order": 25
}

{
  "id": "sin-credito",
  "title": "Sin crédito",
  "description": "Usá solo débito, Bip! o efectivo, nada de tarjeta de crédito.",
  "order": 26
}

{
  "id": "ajuste-de-ruta",
  "title": "Ajuste de ruta",
  "description": "Mirá cómo venías gastando últimamente y ajustá una meta para adelante.",
  "order": 27
}

{
  "id": "uno-menos",
  "title": "Uno menos",
  "description": "Elegí un gasto fijo mensual y reducilo o cancelalo definitivamente.",
  "order": 28
}

{
  "id": "balance-de-la-semana",
  "title": "Balance de la semana",
  "description": "Mirá cuánto lograste ahorrar o gastar mejor esta semana, sin juzgarte, solo con los datos.",
  "order": 29
}

{
  "id": "calma-01-ir-despacio-tambien-es-avanzar",
  "quote": "Ir despacio también es avanzar.",
  "order": 0
}

{
  "id": "calma-02-hoy-no-necesitas-tener-todo-resuelto-solo-dar-un-paso-mas",
  "quote": "Hoy no necesitás tener todo resuelto, solo dar un paso más.",
  "order": 1
}

{
  "id": "calma-03-ordenar-tu-plata-no-es-privarte-es-cuidarte",
  "quote": "Ordenar tu plata no es privarte, es cuidarte.",
  "order": 2
}

{
  "id": "calma-04-un-gasto-que-entendes-ya-no-pesa-igual",
  "quote": "Un gasto que entendés ya no pesa igual.",
  "order": 3
}

{
  "id": "calma-05-no-compares-tu-proceso-con-el-de-nadie-mas",
  "quote": "No compares tu proceso con el de nadie más.",
  "order": 4
}

{
  "id": "calma-06-cada-peso-que-registras-es-un-peso-que-dejas-de-perder-de-vi",
  "quote": "Cada peso que registrás es un peso que dejás de perder de vista.",
  "order": 5
}

{
  "id": "calma-07-la-calma-con-la-plata-se-construye-de-a-poco-no-de-golpe",
  "quote": "La calma con la plata se construye de a poco, no de golpe.",
  "order": 6
}

{
  "id": "calma-08-no-hay-gasto-perfecto-hay-decisiones-que-podes-mejorar",
  "quote": "No hay gasto perfecto, hay decisiones que podés mejorar.",
  "order": 7
}

{
  "id": "calma-09-guardar-500-tambien-cuenta",
  "quote": "Guardar $500 también cuenta.",
  "order": 8
}

{
  "id": "calma-10-equivocarte-con-un-gasto-no-borra-todo-lo-que-veniste-hacien",
  "quote": "Equivocarte con un gasto no borra todo lo que veniste haciendo bien.",
  "order": 9
}

{
  "id": "calma-11-tu-tranquilidad-vale-mas-que-esa-oferta-por-tiempo-limitado",
  "quote": "Tu tranquilidad vale más que esa oferta “por tiempo limitado”.",
  "order": 10
}

{
  "id": "calma-12-ordenar-tus-cuentas-es-un-regalo-para-el-vos-de-manana",
  "quote": "Ordenar tus cuentas es un regalo para el vos de mañana.",
  "order": 11
}

{
  "id": "calma-13-no-se-trata-de-gastar-menos-se-trata-de-gastar-mejor",
  "quote": "No se trata de gastar menos, se trata de gastar mejor.",
  "order": 12
}

{
  "id": "calma-14-un-presupuesto-no-es-una-carcel-es-un-mapa",
  "quote": "Un presupuesto no es una cárcel, es un mapa.",
  "order": 13
}

{
  "id": "calma-15-cada-vez-que-le-decis-no-a-un-gasto-impulsivo-te-decis-si-a-",
  "quote": "Cada vez que le decís “no” a un gasto impulsivo, te decís “sí” a vos.",
  "order": 14
}

{
  "id": "calma-16-la-plata-rinde-mas-cuando-la-miras-de-frente",
  "quote": "La plata rinde más cuando la mirás de frente.",
  "order": 15
}

{
  "id": "calma-17-no-hace-falta-ganar-mas-para-empezar-a-ordenar-lo-que-tenes",
  "quote": "No hace falta ganar más para empezar a ordenar lo que tenés.",
  "order": 16
}

{
  "id": "calma-18-el-primer-paso-no-es-ahorrar-es-animarte-a-mirar",
  "quote": "El primer paso no es ahorrar, es animarte a mirar.",
  "order": 17
}

{
  "id": "calma-19-tu-ritmo-financiero-no-tiene-por-que-ser-el-de-otro",
  "quote": "Tu ritmo financiero no tiene por qué ser el de otro.",
  "order": 18
}

{
  "id": "calma-20-hoy-podes-estar-un-poquito-mas-tranquilo-que-ayer",
  "quote": "Hoy podés estar un poquito más tranquilo que ayer.",
  "order": 19
}

{
  "id": "calma-21-anotar-un-gasto-chico-tambien-es-cuidarte",
  "quote": "Anotar un gasto chico también es cuidarte.",
  "order": 20
}

{
  "id": "calma-22-no-sos-malo-con-la-plata-solo-te-faltaba-un-poco-de-orden",
  "quote": "No sos malo con la plata, solo te faltaba un poco de orden.",
  "order": 21
}

{
  "id": "calma-23-la-calma-tambien-se-ahorra",
  "quote": "La calma también se ahorra.",
  "order": 22
}

{
  "id": "calma-24-cada-suscripcion-que-revisas-es-plata-que-volves-a-elegir-vo",
  "quote": "Cada suscripción que revisás es plata que volvés a elegir vos.",
  "order": 23
}

{
  "id": "calma-25-no-busques-el-mes-perfecto-busca-el-mes-un-poco-mejor",
  "quote": "No busques el mes perfecto, buscá el mes un poco mejor.",
  "order": 24
}

{
  "id": "calma-26-vas-bien-aunque-el-numero-todavia-no-te-cierre-del-todo",
  "quote": "Vas bien, aunque el número todavía no te cierre del todo.",
  "order": 25
}

{
  "id": "calma-27-ordenar-la-plata-tambien-es-ordenar-la-cabeza",
  "quote": "Ordenar la plata también es ordenar la cabeza.",
  "order": 26
}

{
  "id": "calma-28-un-colchon-de-ahorro-es-un-colchon-para-dormir-tranquilo",
  "quote": "Un colchón de ahorro es un colchón para dormir tranquilo.",
  "order": 27
}

{
  "id": "calma-29-no-es-que-no-puedas-es-que-todavia-no-encontraste-tu-metodo",
  "quote": "No es que no puedas, es que todavía no encontraste tu método.",
  "order": 28
}

{
  "id": "calma-30-cada-semana-que-seguis-aca-ya-es-un-logro",
  "quote": "Cada semana que seguís acá, ya es un logro.",
  "order": 29
}
